function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var sorted := numbers.ToArray;
  sorted.Sort;
  for var i := 0 to sorted.Length - 1 do
    for var j := i + 1 to sorted.Length - 1 do
      if Abs(sorted[i] - sorted[j]) < threshold then
      begin
        Result := True;
        exit;
      end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var ignoreSpace := True;
  var stack := new Stack<char>;
  var resultList := new List<string>;
  var tempString := '';
  foreach var ch in parenString do
  begin
    if ignoreSpace and (ch = ' ') then
      continue;
    if ch = '(' then
    begin
      if stack.Count = 0 then
        tempString += '('
      else
        stack.Push('('.Last);
    end
    else if ch = ')' then
    begin
      if stack.Count = 0 then
        tempString += ')'
      else
      begin
        stack.Pop;
        tempString += ')';
      end;
      if stack.Count = 0 then
      begin
        resultList.Add(tempString);
        tempString := '';
      end;
    end;
    ignoreSpace := False;
  end;
  Result := resultList.ToArray;
end;


