  foreach var x in numbers do
  begin
    res.Add(x);
    res.Add(delimeter);
  end;
  res.RemoveAt(res.Count - 1);
  SetLength(Result, res.Count);
  for var i := 0 to res.Count - 1 do
    Result[i] := res[i];
end;


function ParseNestedParens(parenString: string): array of integer;
begin
  var groups := parenString.Split(' ');
  var results := new List<integer>;

  foreach var group in groups do
  begin
    var maxDepth := 0;
    var currentDepth := 0;
    var maxStart := 0;

    for var i := 1 to group.Length do
    begin
      if group[i] = '(' then
        currentDepth += 1
      else if group[i] = ')' then
      begin
        currentDepth -= 1;
        if currentDepth > maxDepth then
        begin
          maxDepth := currentDepth;
          maxStart := i;
        end;
      end;
    end;

    if maxDepth > 0 then
      results.Add(maxDepth + (maxStart - 1))
    else
      results.Add(0);
  end;

  Result := results.ToArray;
end;


