function MakePalindrome(str: string): string;
begin
  var postfix := '';
  for var i := str.Length - 1 downto 0 do
  begin
    if IsPalindrome(str.Substring(i)) then
    begin
      postfix := str.Substring(i);
      break;
    end;
  end;

  if postfix = '' then
    Result := str
  else
  begin
    var prefix := str.Substring(0, str.Length - postfix.Length);
    Result := str + prefix.Inverse;
  end;
end;


