function ParseMusic(musicString: string): array of integer;
begin
  var notes := musicString.Split;
  var beatCount := new List<integer>;
  var beatType := new List<string>;
  var beatCountLast := 0;
  var beatTypeLast := '';
  var beatCountList := new List<integer>;
  var beatTypeList := new List<string>;
  var allBeats := new List<integer>;

  foreach var note in notes do
  begin
    if note = 'o' then
    begin
      allBeats.Add(4);
      beatCountList.Add(beatCountLast + 4);
      beatTypeList.Add(beatTypeLast);
      beatCount += 4;
      beatType += 'o';
    end
    else if note = 'o|' then
    begin
      allBeats.Add(2);
      beatCountList.Add(beatCountLast + 2);
      beatTypeList.Add(beatTypeLast);
      beatCount += 2;
      beatType += 'o|';
    end
    else if note = '.|' then
    begin
      allBeats.Add(1);
      beatCountList.Add(beatCountLast + 1);
      beatTypeList.Add(beatTypeLast);
      beatCount += 1;
      beatType += '.|';
    end;

    if note = 'o' then
      beatCountLast := 0
    else if note = 'o|' then
      beatCountLast := 0
    else if note = '.|' then
      beatCountLast := 0;

    beatTypeLast := note;
  end;

  Result := allBeats.ToArray;
end;


