function Factorize(n: integer): array of integer;
begin
  var i := 2;
  var num := n;
  var factors := new List<integer>;

  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      factors.Add(i);
      num := num div i;
    end
    else
      i := i + 1;
  end;

  if num > 1 then
    factors.Add(num);

  Result := factors.ToArray;
end;


