function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := False;
    exit;
  end;

  if n <= 3 then
  begin
    Result := True;
    exit;
  end;

  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := False;
    exit;
  end;

  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := False;
      exit;
    end;
    i += 6;
  end;

  Result := True;
end;

function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var n := xs.Length;
  if n < 2 then
    raise new System.ArgumentException('xs must have at least two elements');
  if n mod 2 <> 0 then
    raise new System.ArgumentException('xs must have even number of elements');
  var maxPos := 0;
  for var i := 1 to n - 1 do
    if xs[i] > xs[maxPos] then
      maxPos := i;
  case maxPos of
    0: begin Result := -xs[1] / xs[2]; exit; end;
    n-1: begin Result := -xs[n-2] / xs[n-1]; exit; end;
    else begin
      var a := -xs[maxPos] / xs[maxPos + 1];
      var b := -xs[maxPos - 1] / xs[maxPos];
      Result := (a + b) / 2;
      end;
  end;
end;


function SortThird(l: array of integer): array of integer;
