      third.Add(l[i])
    else
      notThird.Add(l[i]);

  third.Sort;
  var res := new List<integer>;
  var thirdIndex := 0;

  for var i := 0 to l.Length - 1 do
    if i mod 3 = 0 then
    begin
      res.Add(third[thirdIndex]);
      thirdIndex += 1;
    end
    else
    begin
      res.Add(notThird[i div 3]);
    end;

  Result := res.ToArray;
end;


