function CorrectBracketing(brackets: string): boolean;
begin
  var stack := new Stack<char>;
  foreach var bracket in brackets do
  begin
    if bracket = '(' then
      stack.Push(bracket)
    else if bracket = ')' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;
  Result := stack.Count = 0;
end;


function Derivative(xs: array of real): array of real;
begin
  var n := xs.Length;
  if n <= 1 then
  begin
    SetLength(Result, 0);
    exit;
  end;
  var res := new real[n - 1];
  for var i := 1 to n - 1 do
    res[i - 1] := (i + 1) * xs[i];
  Result := res;
end;


function Fibfib(n: integer): integer;
begin
  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 0
  else if n = 2 then
    Result := 1
  else
  begin
    var a := 0;
    var b := 0;
    var c := 1;
    for var i := 3 to n do
    begin
      var d := a + b + c;
      a := b;
      b := c;
      c := d;
    end;
    Result := c;
  end;
end;


