function CircularShift(x: integer; shift: integer): string;
begin
  var digits := x.ToString.ToCharArray;
  var n := digits.Length;
  shift := shift mod n;
  var resultStr := '';
  for var i := 0 to n - 1 do
    resultStr := resultStr + digits[(i + shift) mod n];
  Result := resultStr;
end;


