function FruitDistribution(s: string; n: integer): integer;
begin
  var parts := s.Split(' and ');
  var a := parts[0].Split(' ').Last.ToInteger;
  var o := parts[1].Split(' ').Last.ToInteger;
  Result := n - a - o;
end;


function Pluck(arr: array of integer): array of integer;
begin
  var smallestEven := integer.MaxValue;
  var smallestIndex := integer.MaxValue;
  var index := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] mod 2 = 0) and (arr[i] < smallestEven) then
    begin
      smallestEven := arr[i];
      smallestIndex := index;
    end
    else if arr[i] < smallestEven then
    begin
      smallestEven := arr[i];
      smallestIndex := index;
    end;
    index += 1;
  end;

  if smallestEven <> integer.MaxValue then
    Result := |smallestEven, smallestIndex|
  else
    Result := new integer[0];
end;


function Search(lst: array of integer): integer;
