  var freq := new Dictionary<integer, integer>;
  foreach var num in lst do
    if freq.ContainsKey(num) then
      freq[num] += 1
    else
      freq[num] := 1;

  var res := -1;
  for var i := 1 to freq.Count - 1 do
    if freq[i] < i then
    begin
      res := i;
      break;
    end;
  Result := res;
end;


function StrangeSortList(lst: array of integer): array of integer;
begin
  if lst.Length = 0 then
  begin
    SetLength(Result, 0);
    exit;
  end;

  var tempLst := lst.ToArray;
  var sortedLst := tempLst.ToArray;
  sortedLst.Sort;

  var startIndex := 0;
  var endIndex := sortedLst.Length - 1;

  while startIndex < endIndex do
  begin
    for var i := startIndex to endIndex do
      sortedLst[i] := sortedLst[i
    ] + sortedLst[endIndex
    ];
    endIndex -= 1;

    if startIndex = endIndex then
    begin
      sortedLst[startIndex
    ] := sortedLst[startIndex
    ] - sortedLst[endIndex
    ];
      Result := sortedLst;
      exit;
    end;

    for var i := endIndex downto startIndex do
      sortedLst[i
    ] := sortedLst[i
    ] - sortedLst[endIndex
    ];
    endIndex -= 1;

    for var i := startIndex + 1 to endIndex do
    begin
      sortedLst[i
    ] := sortedLst[i
    ] + sortedLst[endIndex
    ];
      sortedLst[endIndex
    ] := sortedLst[endIndex
    ] - sortedLst[i
    ];
    endIndex -= 1;
    startIndex += 1;
  end;

  Result := sortedLst;
end;


function TriangleArea(a, b, c: real): real;
begin
  if (a + b > c) and (a + c > b) and (b + c > a) then
  begin
    var s := (a + b + c) / 2;
    var area := Sqrt(s * (s - a) * (s - b) * (s - c));
    Result := Round(area, 2);
  end
  else
    Result := -1;
end;


