function IsMultiplyPrime(a: integer): boolean;
begin
  var primes := new List<integer>;
  var i := 2;
  while i * i <= a do
  begin
    if a.Divs(i) then
    begin
      primes.Add(i);
      a := a div i;
    end
    else
      i += 1;
  end;
  if (a <> 1) and (primes.Count >= 3) then
  begin
    Result := True;
    exit;
  end;
  Result := False;
end;


