function GetRow(lst: array of array of integer; x: integer): array of (integer, integer);
begin
  var res := new List<(integer, integer)>;
  for var i := 0 to lst.Length - 1 do
    for var j := 0 to lst[i].Length - 1 do
      if lst[i][j] = x then
        res.Add((i, j));
  res.Sort((a, b) -> begin
    if a.Item1 <> b.Item1 then
      Result := a.Item1.CompareTo(b.Item1)
    else
      Result := b.Item2.CompareTo(a.Item2);
  end);
  Result := res.ToArray;
end;


function SortArray(arr: array of integer): array of integer;
begin
  if arr.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var sorted := arr.ToArray;
  sorted.Sort;

  if (arr[0] + arr[arr.Length - 1]) mod 2 = 1 then
    sorted.Reverse
  else
  begin
    var start := 0;
    var finish := arr.Length - 1;

    while start < finish do
    begin
      var temp := sorted[start];
      sorted[start] := sorted[finish];
      sorted[finish] := temp;

      start += 1;
      finish -= 1;
    end;
  end;

  Result := sorted;
end;


function Encrypt(s: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in s do
  begin
    if ch.IsLetter then
    begin
      var shift := 2;
      if ch.IsUpper then
        shift := 1;
      var newChar := Chr((Ord(ch) - Ord('a') + shift) mod 26 + Ord('a'));
      sb.Append(newChar);
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;


function NextSmallest(lst: array of integer): integer;
begin
  if lst.Length < 2 then
  begin
    Result := integer.MaxValue;
    exit;
  end;

  var smallest := integer.MaxValue;
  var secondSmallest := integer.MaxValue;

  foreach var num in lst do
  begin
    if num < smallest then
    begin
      secondSmallest := smallest;
      smallest := num;
    end
    else if (num < secondSmallest) and (num <> smallest) then
      secondSmallest := num;
  end;

  if secondSmallest = integer.MaxValue then
    Result := integer.MaxValue
  else
    Result := secondSmallest;
end;


