function Encode(message: string): string;
begin
  var sb := new StringBuilder;
  foreach var ch in message do
  begin
    if ch.IsLetter then
    begin
      var lowerCh := Char.ToLower(ch);
      if lowerCh.In('aeiou') then
        sb.Append(Char.ToUpper(lowerCh))
      else
        sb.Append((lowerCh.ToInteger + 2).ToString);
    end
    else
      sb.Append(ch);
  end;
  Result := sb.ToString;
end;


function IsPrime(num: integer): boolean;
begin
  if num < 2 then
    Result := False
  else
  begin
    Result := True;
    for var i := 2 to Trunc(Sqrt(num)) do
      if num mod i = 0 then
      begin
        Result := False;
        break;
      end;
  end;
end;

function SumOfDigits(num: integer): integer;
