function CheckDictCase(dict: Dictionary<string, string>): boolean;
begin
  if dict.Count = 0 then
  begin
    Result := False;
    exit;
  end;

  var allLower := True;
  var allUpper := True;

  foreach var kv in dict do
  begin
    if not kv.Key.All(c -> c.IsLower) then
      allLower := False;
    if not kv.Key.All(c -> c.IsUpper) then
      allUpper := False;
  end;

  Result := allLower or allUpper;
end;


function CountUpTo(n: integer): array of integer;
begin
  if n <= 2 then
  begin
    SetLength(Result, 0);
    exit;
  end;

  var primes := new List<integer>;
  primes.Add(2);

  for var num := 3 to n - 1 step 2 do
  begin
    var isPrime := True;
    foreach var prime in primes do
    begin
      if Sqr(prime) > num then
        break;
      if num mod prime = 0 then
      begin
        isPrime := False;
        break;
      end;
    end;
    if isPrime then
      primes.Add(num);
  end;

  Result := primes.ToArray;
end;


