function WordsString(s: string): array of string;
begin
  var specials := ' ,.';
  var trimmed := s.Trim;
  if trimmed.Length = 0 then
  begin
    SetLength(Result, 0);
    exit;
  end;
  var start := 1;
  SetLength(Result, trimmed.Length);
  for var i := 1 to trimmed.Length do
  begin
    if specials.Contains(trimmed[i]) then
    begin
      Result[i - 1] := trimmed.Substring(start, i - start);
      start := i + 1;
    end;
  end;
  Result[Result.Length - 1] := trimmed.Substring(start - 1);
end;


