function RoundedAvg(n, m: integer): string;
begin
  if n > m then
  begin
    Result := '-1';
    exit;
  end;

  var total := 0;
  for var i := n to m do
    total += i;

  var avg := Round(total / (m - n + 1));
  Result := '0b' + Convert.ToString(avg, 2);
end;


function UniqueDigits(x: array of integer): array of integer;
begin
  var uniqueDigits := new List<integer>;

  foreach var num in x do
  begin
    var numStr := num.ToString;
    var hasEvenDigit := False;

    for var i := 1 to numStr.Length do
    begin
      if (StrToInt(numStr[i].ToString) mod 2 <> 0) then
      begin
        hasEvenDigit := True;
        break;
      end;
