  begin
    Result := emptyArray;
    exit;
  end;

  var sorted := arr.Where(num -> (num >= 1) and (num <= 9)).ToArray;
  sorted.Sort;
  var reversed := sorted.Reverse.ToArray;

  var res := new string[reversed.Length];
  for var i := 0 to reversed.Length - 1 do
  begin
