function EvenOddPalindrome(n: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  for var i := 1 to n do
  begin
    var isPalindrome := True;
    var num := i;
    while num > 0 do
    begin
      if num mod 10 = 0 then
        isPalindrome := False
      else
      begin
        var reversed: integer := 0;
        while num > 0 do
        begin
          reversed := reversed * 10 + (num mod 10);
          num := num div 10;
        end;
        if reversed <> num then
          isPalindrome := False;
      end;
      num := num div 10;
    end;
    if isPalindrome then
      if i mod 2 = 0 then
        evenCount += 1
      else
        oddCount += 1;
  end;
  Result := (evenCount, oddCount);
end;


function CountNums(arr: array of integer): integer;
begin
  var count := 0;
  foreach var num in arr do
  begin
    if num < 0 then
    begin
      var digits := Abs(num);
      while digits > 0 do
      begin
        if digits mod 10 > 0 then
          count += 1;
        digits := digits div 10;
      end;
    end
    else
    begin
      var digits := num;
      while digits > 0 do
      begin
        if digits mod 10 > 0 then
          count += 1;
        digits := digits div 10;
      end;
    end;
  end;
  Result := count;
end;


