function Exchange(lst1, lst2: array of integer): string;
begin
  var oddCount1 := 0;
  var oddCount2 := 0;
  var evenCount1 := 0;
  var evenCount2 := 0;

  for var i := 0 to lst1.Length - 1 do
  begin
    if lst1[i] mod 2 <> 0 then
      oddCount1 += 1;
    if lst2[i] mod 2 <> 0 then
      oddCount2 += 1;
  end;

  for var i := 0 to lst1.Length - 1 do
  begin
    if lst1[i] mod 2 = 0 then
      evenCount1 += 1;
    if lst2[i] mod 2 = 0 then
      evenCount2 += 1;
  end;

  if (oddCount1 + evenCount2) <> (oddCount2 + evenCount1) then
    Result := 'NO'
  else
    Result := 'YES';
end;


function Histogram(test: string): Dictionary<string, integer>;
begin
  var parts := test.Split(' ');
  var counts := new Dictionary<string, integer>;
  var maxCount := 0;
  var res := new Dictionary<string, integer>;

  foreach var word in parts do
  begin
    if word <> '' then
    begin
      if counts.ContainsKey(word) then
        counts[word] += 1
      else
        counts[word] := 1;

      if counts[word] > maxCount then
        maxCount := counts[word];
    end;
  end;

  foreach var kv in counts do
  begin
    if kv.Value = maxCount then
      res[kv.Key] := maxCount;
  end;

  Result := res;
end;


function ReverseDelete(s, c: string): (string, boolean);
begin
  var sb := new StringBuilder;
  foreach var ch in s do
    if ch <> '*' then
      if ch <> c[ch - 'a' + 1] then
        sb.Append(ch);
  var res := sb.ToString;
  var l := 1;
  var r := res.Length;
  var flag := False;
  while l < r do
  begin
    if res[l] <> res[r] then
    begin
      flag := False;
      break;
    end
    else
    begin
      flag := True;
      l += 1;
      r -= 1;
    end;
  end;
  Result := (res, flag);
end;


