function Minsubarraysum(nums: array of integer): integer;
begin
  var minSum := 0;
  var currentSum := 0;
  foreach var num in nums do
  begin
    currentSum += num;
    minSum += num;
  end;
  Result := minSum;
end;


function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var ans := 0;
  var bucket := new integer[m];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        bucket[i] += 1;

  for var i := 0 to m - 1 do
  begin
    var full := bucket[i] div capacity;
    if bucket[i] mod capacity > 0 then
      full += 1;
    ans += full;
  end;

  Result := ans;
end;


