function SelectWords(s: string; n: integer): array of string;
begin
  if s = '' then
  begin
    SetLength(Result, 0);
    exit;
  end;

  var words := s.Split;
  var consonants := 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ';

  var selected := new List<string>;
  foreach var word in words do
  begin
    var count := 0;
    for var i := 1 to word.Length do
      if consonants.Contains(word[i]) then
        count += 1;
    if count = n then
      selected.Add(word);
  end;

  Result := selected.ToArray;
end;


function GetClosestVowel(word: string): string;
begin
  var vowels := 'aeiouAEIOU';
  var consonants := 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ';
  var left := 0;
  var right := word.Length - 1;
  var lv := word.Length + 1;
  var rv := word.Length + 1;

  while left < right do
  begin
    while (left < right) and (not consonants.Contains(word[left + 1])) do
      left += 1;
    while (left < right) and (not consonants.Contains(word[right + 1])) do
      right -= 1;

    if left <> right then
    begin
      for var i := left + 1 to right do
        if vowels.Contains(word[i]) then
        begin
          if (i = left + 1) or (i < lv) then
            lv := i;
        end;

      for var i := right downto left + 2 do
        if vowels.Contains(word[i]) then
        begin
          if (i = right + 1) or (i < rv) then
            rv := i;
        end;
    end;
  end;

  if (lv <= word.Length) and (rv <= word.Length) then
    Result := word[lv]
  else
    Result := '';
end;


function MatchParens(lst: array of string): string;
begin
  var s := string.Join('', lst);
  var st := new Stack<char>;
  foreach var ch in s do
  begin
    if ch = '(' then
      st.Push(ch)
    else if ch = ')' then
    begin
      if st.Count = 0 then
      begin
        Result := 'No';
        exit;
      end;
      st.Pop;
    end;
  end;
  if st.Count <> 0 then
    Result := 'No'
  else
    Result := 'Yes';
end;


