function GetOddCollatz(n: integer): array of integer;
begin
  var seq := new List<integer>;
  seq.Add(1);
  var num := n;

  while num <> 1 do
  begin
    if num mod 2 <> 0 then
      seq.Add(num);
    num := num div 2;
    if num mod 2 <> 0 then
      seq.Add(num + 1);
    num := num div 2;
  end;

  Result := seq.Order.ToArray;
end;


