  begin
    Result := False;
    exit;
  end;

  var mm, dd, yyyy: integer;
  if not TryStrToInt(parts[0], mm) or not TryStrToInt(parts[1], dd) or not TryStrToInt(parts[2], yyyy) then
  begin
    Result := False;
    exit;
  end;

  if (mm < 1) or (mm > 12) or (dd < 1) or (dd > 31) then
  begin
    Result := False;
    exit;
  end;

  if (mm = 4) or (mm = 6) then
  begin
    if dd < 1 then
    begin
      Result := False;
      exit;
    end;
    if dd > 30 then
    begin
      Result := False;
      exit;
    end;
  end
  else if (mm = 2) then
  begin
    if dd < 1 then
    begin
      Result := False;
      exit;
    end;
