    begin
      Result := False;
      exit;
    end;
  end
  else
  begin
    if dd < 1 then
    begin
      Result := False;
      exit;
    end;
    if dd > 31 then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;


