function IsSorted(lst: array of integer): boolean;
begin
  if lst.Length = 0 then
  begin
    Result := True;
    exit;
  end;

  var hasDuplicate := False;

  for var i := 0 to lst.Length - 2 do
    if lst[i] = lst[i + 1] then
    begin
      hasDuplicate := True;
      break;
    end;

  Result := not hasDuplicate;
end;


function Intersection(interval1, interval2: array of integer): string;
begin
  var start := Max(interval1[0], interval2[0]);
  var endVal := Min(interval1[1], interval2[1]);
  var length := endVal - start;
  Result := if IsPrime(length) then 'YES' else 'NO';
end;


function ProdSigns(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var prod := 1;
  var sum := 0;

  foreach var num in arr do
  begin
    if num = 0 then
    begin
      Result := 0;
      exit;
    end;

    if num < 0 then
      sign := -1
    else
      sign := 1;

    prod := prod * sign;
    sum := sum + Abs(num);
  end;

  Result := prod * sum;
end;


function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var visited := new HashSet<(integer, integer)>;
  var queue := new Queue<(integer, integer, integer)>;
  var ans := new List<integer>;

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
    begin
      visited.Add((i, j));
      queue.Enqueue((i, j, grid[i][j]));
    end;

  while (queue.Count > 0) and (ans.Count < k) do
  begin
    var (x, y, val) := queue.Dequeue;
    ans.Add(val);

    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and 
         not visited.Contains((nx, ny)) then
      begin
        visited.Add((nx, ny));
        queue.Enqueue((nx, ny, grid[nx][ny]));
      end;
    end;
  end;

  Result := ans.ToArray;
end;


function Tri(n: integer): array of real;
begin
  var trib := new List<real>;
  trib.Add(3);

  for var i := 1 to n do
  begin
    if i mod 2 = 0 then
      trib.Add(i div 2)
    else
    begin
      if trib.Count < i + 1 then
        trib.Add(trib[i - 1] + trib[i - 2] + trib[i]);
      else
        trib[i] := trib[i] + trib[i - 1] + trib[i - 2];
    end;
  end;

  Result := trib.ToArray;
end;


function Digits(n: integer): integer;
begin
  var product := 1;
  var hasOdd := False;
  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 <> 0 then
    begin
      product *= digit;
      hasOdd := True;
    end;
    n := n div 10;
  end;
  if hasOdd then
    Result := product
  else
    Result := 0;
end;


function IsNested(s: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if (ch = '[') or (ch = '{') or (ch = '(') then
      stack.Push(ch)
    else if (ch = ']') or (ch = '}') or (ch = ')') then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;

      var top := stack.Peek;
      if ((top = '[') and ((ch = ']') or (ch = '}'))) or 
         ((top = '(') and ((ch = ')') or (ch = '}'))) or 
         ((top = '{') and ((ch = '}') or (ch = ']')))) then
        stack.Pop
      else
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;


