function LargestSmallestIntegers(lst: array of integer): (integer, integer);
begin
  var maxNegative := integer.MinValue;
  var minPositive := integer.MaxValue;
  var hasNegative := false;
  var hasPositive := false;

  foreach var num in lst do
  begin
    if num < 0 then
    begin
      if not hasNegative then
      begin
        maxNegative := num;
        hasNegative := true;
      end
      else if num > maxNegative then
        maxNegative := num;
    end
    else if num > 0 then
    begin
      if not hasPositive then
      begin
        minPositive := num;
        hasPositive := true;
      end
      else if num < minPositive then
        minPositive := num;
    end;
  end;

  if hasNegative then
    Result := (maxNegative, minPositive)
  else
    Result := (0, 0);
end;


function CompareOne(a, b: object): object;
begin
  var aType := a.GetType;
  var bType := b.GetType;

  if aType <> bType then
  begin
    if (aType = typeof(integer)) or (aType = typeof(shortint)) or (aType = typeof(byte)) or (aType = typeof(longint)) or (aType = typeof(integer)) or (aType = typeof(shortint)) or (aType = typeof(byte)) or (aType = typeof(longint)) then
    begin
      var aVal := integer.Parse(a.ToString);
      var bVal := integer.Parse(b.ToString);
      Result := if aVal > bVal then a else b;
    end
    else if (aType = typeof(float)) or (aType = typeof(double)) or (aType = typeof(decimal)) then
    begin
      var aVal := Convert.ToDouble(a);
      var bVal := Convert.ToDouble(b);
      Result := if aVal > bVal then a else b;
    end
    else if (aType = typeof(string)) or (bType = typeof(string)) then
    begin
      var aVal := Convert.ToDouble(a.ToString);
      var bVal := Convert.ToDouble(b.ToString);
      Result := if aVal > bVal then a else b;
    end;
  end
  else
  begin
    if a = b then
      Result := nil
    else
      Result := b;
  end;
end;


function IsEqualToSumEven(n: integer): boolean;
begin
  if n mod 2 <> 0 then
    Result := False
  else
  begin
    var a := 2;
    var b := 2;
    var c := 2;
    var d := n - 2;
    Result := (a = b) or (b = c) or (c = d) or (d = a);
    while Result = False do
    begin
      a += 2;
      b += 2;
      c += 2;
      d -= 2;
      Result := (a = b) or (b = c) or (c = d) or (d = a);
    end;
  end;
end;


function SpecialFactorial(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else
  begin
    var res := 1;
    for var i := 1 to n do
      res := res * i;
    Result := res;
  end;
end;


function FixSpaces(text: string): string;
begin
  var sb := new StringBuilder;
  var prevCharWasSpace := False;
  var prevWasSpace := False;
  var doubleSpaceCount := 0;

  for var i := 1 to text.Length do
  begin
    var ch := text[i];
    if ch = ' ' then
    begin
      if not prevCharWasSpace then
      begin
        if doubleSpaceCount > 0 then
        begin
          sb.Append('-');
          doubleSpaceCount := 0;
        end;
        sb.Append('_');
      end;
      prevCharWasSpace := True;
    end
    else
    begin
      sb.Append(ch);
      prevCharWasSpace := False;
    end;

    if ch = ' ' then
    begin
      doubleSpaceCount += 1;
      if doubleSpaceCount > 1 then
        sb.Append('-')
      else
      begin
        if not prevWasSpace then
        begin
          if doubleSpaceCount = 1 then
            sb.Append('_')
          else
            sb.Append('-');
        end;
      end;
    end
    else
      doubleSpaceCount := 0;

    prevWasSpace := ch = ' ';
  end;

  Result := sb.ToString;
end;


function FileNameCheck(fileName: string): string;
begin
  var parts := fileName.Split('.');
  if parts.Length <> 2 then
    Result := 'No'
  else
  begin
    var namePart := parts[0];
    var extensions := |'txt', 'exe', 'dll'|;

    if namePart.Length > 3 then
      Result := 'No'
    else if not namePart[1].IsLower then
      Result := 'No'
    else if not namePart.Any(c -> c.IsDigit) then
      Result := 'No'
    else if not extensions.Contains(parts[1]) then
      Result := 'No'
    else
      Result := 'Yes';
  end;
end;


function SumSquares(lst: array of integer): integer;
begin
  var sum := 0;
  for var i := 0 to lst.Length - 1 do
  begin
    if (i mod 3 = 0) and (i mod 4 <> 0) then
      sum += lst[i] * lst[i] * lst[i]
    else if (i mod 4 = 0) and (i mod 3 <> 0) then
      sum += lst[i] * lst[i] * lst[i] * lst[i];
  end;
  Result := sum;
end;


