function OrderByPoints(nums: array of integer): array of integer;
begin
  var sumDigits := new List<(integer, integer)>;

  for var i := 0 to nums.Length - 1 do
    sumDigits.Add((nums[i].Abs.Sum, i));

  sumDigits.Sort((x, y) -> 
  begin
    if x.Item1 <> y.Item1 then
      Result := x.Item1.CompareTo(y.Item1)
    else
      Result := x.Item2.CompareTo(y.Item2);
  end);

  Result := new integer[nums.Length];
  for var i := 0 to sumDigits.Count - 1 do
    Result[i] := nums[sumDigits[i].Item2];
end;


