function GetMaxTriples(n: integer): integer;
begin
  var a := new integer[n];
  for var i := 0 to n - 1 do
    a[i] := i * i - i + 1;

  var count := 0;

  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
      for var k := j + 1 to n - 1 do
        if (a[i] + a[j] + a[k]) mod 3 = 0 then
          count += 1;

  Result := count;
end;


function Bf(planet1, planet2: string): array of string;
begin
  var planets := new List<string>;
  planets.AddRange(Arr('Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune'));

  if (not planets.Contains(planet1)) or (not planets.Contains(planet2)) then
  begin
    Result := new string[0];
    exit;
  end;

  var idx1 := planets.IndexOf(planet1);
  var idx2 := planets.IndexOf(planet2);

  if idx1 < idx2 then
    Result := planets.GetRange(idx1 + 1, idx2 - idx1 - 1)
  else
    Result := planets.GetRange(idx2 + 1, idx1 - idx2 - 1);
end;


