  var aa := a + a;
  var flag := False;

  for var i := 0 to n1 - 1 do
  begin
    var &match := True;
    for var j := 0 to n2 - 1 do
      if aa[i + j] <> b[j] then
      begin
        &match := False;
        break;
      end;
    if &match then
    begin
      flag := True;
      break;
    end;
  end;

  if flag then
    Result := True
  else
  begin
    for var i := 0 to n2 - 1 do
    begin
      var c := b[i];
      var s := b.Substring(i) + b.Substring(0, i);
      if aa.Contains(s) then
      begin
        Result := True;
        exit;
      end;
    end;
    Result := False;
  end;
end;


function EvenOddCount(num: integer): (integer, integer);
begin
  var evenCount := 0;
  var oddCount := 0;
  var n := Abs(num);

  while n > 0 do
  begin
    var digit := n mod 10;
    if digit mod 2 = 0 then
      evenCount += 1
    else
      oddCount += 1;
    n := n div 10;
  end;

  Result := (evenCount, oddCount);
end;


function IntToMiniRoman(number: integer): string;
begin
  if number = 0 then
    exit('');
  var values := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1|;
  var symbols := |'m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i'|;
  var roman := '';
  var remaining := number;
  for var i := 0 to values.Length - 1 do
  begin
    while remaining >= values[i] do
    begin
      roman += symbols[i];
      remaining -= values[i];
    end;
  end;
  Result := roman.ToLower;
end;


function RightAngleTriangle(a, b, c: integer): boolean;
begin
  Result := (a * a + b * b = c * c) or (b * b + c * c = a * a) or (c * c + a * a = b * b);
end;


function FindMax(words: array of string): string;
begin
  var maxUnique := 0;
  var resultWord := '';
  foreach var word in words do
  begin
    var uniqueChars := new HashSet<char>(word.ToCharArray);
    if uniqueChars.Count > maxUnique then
    begin
      maxUnique := uniqueChars.Count;
      resultWord := word;
    end;
  end;
  Result := resultWord;
end;


function Eat(number, need, remaining: integer): (integer, integer);
begin
  if remaining >= need then
  begin
    Result := (number + need, remaining - need);
    exit;
  end;
  Result := (number + remaining, 0);
end;


function DoAlgebra(op: array of string; operand: array of integer): integer;
begin
  var res := operand[0];
  for var i := 0 to op.Length - 1 do
  begin
    case op[i] of
      '+': res += operand[i + 1];
      '-': res -= operand[i + 1];
      '*': res *= operand[i + 1];
      '//': res := res div operand[i + 1];
      '**': res := Round(Power(res, operand[i + 1]));
    end;
  end;
  Result := res;
end;


function Solve(s: string): string;
begin
  var letters := new List<char>;
  var digits := new List<char>;
  var other := new List<char>;

  foreach var ch in s do
    if ch.IsLetter then
      letters.Add(ch)
    else if ch.IsDigit then
      digits.Add(ch)
    else
      other.Add(ch);

  if letters.Count = 0 then
  begin
    var chars := s.ToCharArray;
    &Array.Reverse(chars);
    Result := new string(chars);
  end
  else
  begin
    letters.Reverse;
    var res := new string(letters.ToArray);

    for var i := 0 to digits.Count - 1 do
      res[i + 1] := digits[i];

    Result := res;
  end;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
    exit(nil);
  var md5 := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var bytes := Encoding.Default.GetBytes(text);
  var hash := md5.ComputeHash(bytes);
  Result := string.Join('', hash.Select(b -> b.ToString('x2')));
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var evenNumbers := new List<integer>;

  for var num := a to b do
    if (num mod 2 = 0) and (num <> 0) then
      evenNumbers.Add(num);

  Result := evenNumbers.ToArray;
end;
